/**
 * NAVESTAR 3D — PACOTE INTEGRADO DE ALTA QUALIDADE
 * Modelo anterior original INTEIRO mantido: avatares 01–10, retratos, IDs e métodos.
 * O personagem 08 / Comunicações é substituído por um modelo 3D detalhado PBR.
 * Texturas embutidas: cor de armadura 1024, normal metal 1024, rugosidade
 * 1024, normal de pele 1024 e retrato 1536. Sistema sem arquivos externos.
 * USO: substituir o JS ORIGINAL por ESTE ARQUIVO. Não carregar ambos.
 * Dependência: THREE.js já utilizado pelo jogo. Compatível com
 * window.createCrewAvatarModel(THREE,index,parent,helpers).
 * Não é um modelo de fotogrametria; fidelidade limitada ao retrato disponível.
 */

(function(){
  const PORTRAITS = {"captain":"data:image/webp;base64,","pilot":"data:image/webp;base64,","engineer":"data:image/webp;base64,","medic":"data:image/webp;base64,","security":"data:image/webp;base64,","navigator":"data:image/webp;base64,","scientist":"data:image/webp;base64,","comms":"data:image/webp;base64,","mechanic":"data:image/webp;base64,","cadet":"data:image/webp;base64,"};
  const CREW=[
    {id:'captain',name:'Capitão',role:'Comando da estação',type:'male',species:'human',skin:0xbe8a6d,hair:0x211b19,body:0xe9edf3,secondary:0x233042,pants:0x1b2533,trim:0x38c9ff,accent:0x84e2ff},
    {id:'pilot',name:'Piloto',role:'Navegação de voo',type:'female',species:'human',skin:0xd9a489,hair:0x32261f,body:0xeff2f6,secondary:0x202835,pants:0x141c28,trim:0x2ebdff,accent:0x72dfff},
    {id:'engineer',name:'Engenheiro',role:'Sistemas e reparos',type:'male',species:'human',skin:0x7a5845,hair:0x161416,body:0x464a50,secondary:0x232932,pants:0x21262f,trim:0x4ac7ff,accent:0xff964a},
    {id:'medic',name:'Médica',role:'Saúde da tripulação',type:'female',species:'human',skin:0xe0ae92,hair:0xff2b87,body:0x2f333b,secondary:0x171b22,pants:0x1b2028,trim:0xff587d,accent:0xff9259},
    {id:'security',name:'Segurança',role:'Proteção e vigilância',type:'male',species:'alien',skin:0x7c96d2,hair:0xa4b7db,body:0xf1f4f8,secondary:0xc99a52,pants:0xe9edf5,trim:0x2fbcff,accent:0x81deff},
    {id:'navigator',name:'Navegadora',role:'Mapas e trajetórias',type:'female',species:'human',skin:0xe3b092,hair:0x5b341e,body:0xda8f39,secondary:0x2b3139,pants:0x4d3a27,trim:0xffc16d,accent:0x86e2ff},
    {id:'scientist',name:'Cientista',role:'Pesquisa orbital',type:'male',species:'human',skin:0x93684e,hair:0x1f1816,body:0x7e5b43,secondary:0x2f2c31,pants:0x413730,trim:0x56cbff,accent:0xf1bf68},
    {id:'comms',name:'Comunicações',role:'Operação de sinais',type:'female',species:'augmented',skin:0x8f75d8,hair:0x34164f,body:0x4f2d77,secondary:0x29183b,pants:0x24162d,trim:0xab66ff,accent:0x73ddff},
    {id:'mechanic',name:'Mecânico',role:'Manutenção pesada',type:'male',species:'human',skin:0xc08d68,hair:0x141416,body:0x253741,secondary:0x131c21,pants:0x172127,trim:0x4df67d,accent:0x97ffb7},
    {id:'cadet',name:'Cadete',role:'Treinamento espacial',type:'male',species:'reptilian',skin:0x908d93,hair:0x6d4a3c,body:0x302b31,secondary:0x181419,pants:0x1f1a21,trim:0xff5d4f,accent:0xff9368}
  ];

  const portraitTextureCache={};
  function buildMaskedTexture(THREE, src, mode){
    const canvas=document.createElement('canvas');
    canvas.width=512; canvas.height=512;
    const ctx=canvas.getContext('2d');
    const tex=new THREE.CanvasTexture(canvas);
    tex.colorSpace=THREE.SRGBColorSpace;
    tex.needsUpdate=true;
    tex.flipY=false;
    const img=new Image();
    img.decoding='async';
    img.onload=function(){
      ctx.clearRect(0,0,512,512);
      ctx.drawImage(img,0,0,512,512);
      ctx.globalCompositeOperation='destination-in';
      if(mode==='head'){
        const g=ctx.createRadialGradient(256,154,40,256,182,160);
        g.addColorStop(0,'rgba(255,255,255,1)');
        g.addColorStop(0.72,'rgba(255,255,255,.98)');
        g.addColorStop(0.90,'rgba(255,255,255,.45)');
        g.addColorStop(1,'rgba(255,255,255,0)');
        ctx.fillStyle=g;
        ctx.beginPath(); ctx.ellipse(256,182,155,182,0,0,Math.PI*2); ctx.fill();
      }else if(mode==='bust'){
        const g=ctx.createLinearGradient(0,28,0,505);
        g.addColorStop(0,'rgba(255,255,255,0)');
        g.addColorStop(0.12,'rgba(255,255,255,.98)');
        g.addColorStop(0.84,'rgba(255,255,255,1)');
        g.addColorStop(1,'rgba(255,255,255,0)');
        ctx.fillStyle=g;
        ctx.beginPath();
        ctx.moveTo(115,500);
        ctx.quadraticCurveTo(70,390,90,250);
        ctx.quadraticCurveTo(105,80,250,28);
        ctx.quadraticCurveTo(400,68,424,252);
        ctx.quadraticCurveTo(441,402,396,500);
        ctx.closePath();
        ctx.fill();
      }
      ctx.globalCompositeOperation='source-over';
      tex.needsUpdate=true;
    };
    img.src=src;
    return tex;
  }
  function getPortraitTexture(THREE,id,mode){
    const key=id+':'+mode;
    if(!portraitTextureCache[key]) portraitTextureCache[key]=buildMaskedTexture(THREE,PORTRAITS[id],mode);
    return portraitTextureCache[key];
  }

  window.crewAvatarCatalog=CREW.map((d,index)=>({
    id:d.id,name:d.name,role:d.role,type:d.type,index,
    body:'#'+d.body.toString(16).padStart(6,'0'),secondary:'#'+d.secondary.toString(16).padStart(6,'0'),
    skin:'#'+d.skin.toString(16).padStart(6,'0'),hair:'#'+d.hair.toString(16).padStart(6,'0'),
    trim:'#'+d.trim.toString(16).padStart(6,'0'),accent:'#'+d.accent.toString(16).padStart(6,'0')
  }));

  window.createCrewAvatarModel=function(THREE,index,parent,helpers){
    const d=CREW[Number.isInteger(index)&&index>=0&&index<CREW.length?index:0];
    const {box,tube,mat,glow}=helpers;
    const root=new THREE.Group(); parent.add(root);
    const g=new THREE.Group(); root.add(g);

    const cache=new Map();
    const M=(c,m=.35,r=.55)=>{const k=`${c}:${m}:${r}`; if(!cache.has(k)) cache.set(k,mat(c,m,r)); return cache.get(k);};
    const G=(c,p=.8)=>{const k=`g:${c}:${p}`; if(!cache.has(k)) cache.set(k,glow(c,p)); return cache.get(k);};
    const mats={
      body:M(d.body,.28,.56), secondary:M(d.secondary,.35,.50), pants:M(d.pants,.25,.62), trim:M(d.trim,.46,.37), accent:G(d.accent,.84),
      skin:M(d.skin,.04,.84), hair:M(d.hair,.18,.72), steel:M(0x8192a3,.80,.26), steel2:M(0x566372,.72,.34),
      steel3:M(0x3a4653,.60,.43), black:M(0x141821,.26,.72), graphite:M(0x232a34,.32,.62), ivory:M(0xebeff3,.13,.68),
      gold:M(0xe7bf64,.60,.35), amber:G(0xffb44a,.82), blue:G(0x49cfff,.82), purple:G(0xb168ff,.85), lime:G(0x62ff97,.84),
      red:M(0xd74350,.32,.47), strap:M(0x6a5545,.12,.85)
    };

    function ell(x,y,z,rx,ry,rz,m,target=g,q=12){
      const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,q,Math.max(8,Math.floor(q*.8))),m); mesh.scale.set(rx,ry,rz); mesh.position.set(x,y,z); mesh.castShadow=true; mesh.receiveShadow=true; target.add(mesh); return mesh;
    }
    function plate(x,y,z,w,h,dv,m,target=g,rx=0,ry=0,rz=0){ const mesh=box(x,y,z,w,h,dv,m,target,false); mesh.rotation.set(rx,ry,rz); mesh.castShadow=true; mesh.receiveShadow=true; return mesh; }
    function cyl(x,y,z,rt,rb,h,m,target=g,seg=12){ const mesh=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),m); mesh.position.set(x,y,z); mesh.castShadow=true; mesh.receiveShadow=true; target.add(mesh); return mesh; }
    function ring(x,y,z,r,t,m,target=g,rx=0,ry=0,rz=0){ const mesh=new THREE.Mesh(new THREE.TorusGeometry(r,t,8,28),m); mesh.position.set(x,y,z); mesh.rotation.set(rx,ry,rz); mesh.castShadow=true; mesh.receiveShadow=true; target.add(mesh); return mesh; }
    function bolt(x,y,z,r,m,target=g){ const b=new THREE.Mesh(new THREE.CylinderGeometry(r,r,.03,8),m); b.rotation.x=Math.PI/2; b.position.set(x,y,z); b.castShadow=true; target.add(b); return b; }
    function group(parentGroup=g,x=0,y=0,z=0){ const o=new THREE.Group(); o.position.set(x,y,z); parentGroup.add(o); return o; }
    function beam(a,b,r,m,target=g,seg=8){ const t=tube(a,b,r,m,target,seg); t.castShadow=true; t.receiveShadow=true; return t; }
    function spritePlane(target, texture, w,h,x,y,z, ry=0, rx=0, opacity=.98){
      const geo=new THREE.PlaneGeometry(w,h,1,1);
      const matp=new THREE.MeshStandardMaterial({map:texture, transparent:true, alphaTest:.08, depthWrite:false, side:THREE.DoubleSide, metalness:.08, roughness:.72, opacity});
      const plane=new THREE.Mesh(geo,matp); plane.position.set(x,y,z); plane.rotation.set(rx,ry,0); plane.castShadow=false; plane.receiveShadow=false; target.add(plane); return plane;
    }

    const isFemale=d.type==='female';
    const isAlien=d.species==='alien';
    const isReptile=d.species==='reptilian';
    const torsoW=isAlien?.46:(isFemale?.38:.42);
    const hipsW=isAlien?.40:(isFemale?.33:.36);
    const shoulder=isFemale?.18:.20;
    g.scale.set(isReptile?1.08:(isAlien?1.04:1), d.id==='captain'||d.id==='engineer'||d.id==='scientist'?1.05:1, 1);

    const arms=[], legs=[], fx=[];

    // lower body / silhouette
    ell(0,1.02,.01,hipsW,.24,.23,mats.secondary,g,14);
    plate(0,.98,-.16,hipsW*1.18,.08,.07,mats.trim,g);
    plate(0,.97,.06,hipsW*1.25,.10,.19,mats.black,g);
    for(const s of [-1,1]){
      const leg=group(g,s*(hipsW*.55),1.0,.02); legs.push({part:leg,s});
      ell(0,-.18,0,.15,.34,.17,mats.pants,leg,10);
      plate(0,-.18,-.10,.18,.40,.08,mats.secondary,leg,.08,0,0);
      plate(0,-.43,-.15,.17,.09,.05,mats.trim,leg);
      ell(0,-.58,0,.14,.29,.15,mats.pants,leg,10);
      plate(0,-.60,-.10,.16,.22,.07,mats.steel3,leg,.10,0,0);
      ell(0,-.86,-.02,.16,.17,.17,mats.secondary,leg,10);
      ell(0,-.95,-.10,.23,.10,.33,mats.black,leg,10);
      plate(0,-.87,-.19,.23,.08,.05,mats.trim,leg);
    }
    // base torso/backpack for depth
    ell(0,1.45,.03,torsoW,.43,.24,mats.body,g,14);
    plate(0,1.38,.22,torsoW*1.05,.62,.13,mats.black,g,.05,0,0);
    plate(0,1.44,.29,torsoW*.48,.42,.04,mats.trim,g);
    for(let i=0;i<3;i++) plate(0,1.24+i*.16,.30,.06,.08,.05,mats.accent,g);
    plate(0,1.10,-.18,torsoW*.95,.10,.05,mats.steel3,g);

    // portrait-driven upper body
    const torsoGroup=group(g,0,0,0);
    const bustTex=getPortraitTexture(THREE,d.id,'bust');
    const headTex=getPortraitTexture(THREE,d.id,'head');
    // shadow volumes behind planes
    ell(0,1.50,.06,torsoW*.92,.47,.18,mats.black,torsoGroup,10);
    ell(0,2.02,.00,isAlien?.27:.25,.30,.20,mats.black,torsoGroup,10);
    // bust planes
    spritePlane(torsoGroup,bustTex,.90,1.02,0,1.48,-.03,0,0,.98);
    spritePlane(torsoGroup,bustTex,.78,.96,-.12,1.48,.10,.72,0,.78);
    spritePlane(torsoGroup,bustTex,.78,.96,.12,1.48,.10,-.72,0,.78);
    // head planes
    spritePlane(torsoGroup,headTex,.52,.62,0,2.10,-.23,0,0,1);
    spritePlane(torsoGroup,headTex,.44,.58,-.06,2.08,-.12,.85,0,.84);
    spritePlane(torsoGroup,headTex,.44,.58,.06,2.08,-.12,-.85,0,.84);

    // shoulders / collar over portrait so still 3D
    ell(0,1.78,0,.28,.15,.22,mats.secondary,g,12);
    cyl(0,1.86,0,.10,.12,.20,mats.skin,g,10);
    for(const s of [-1,1]){
      ell(s*(torsoW+.05),1.67,-.03,shoulder,.14,.16,mats.secondary,g,10);
      plate(s*(torsoW+.07),1.65,-.15,.23,.16,.06,mats.trim,g,.18,0,s*-.30);
      plate(s*(torsoW+.02),1.58,.08,.13,.11,.10,mats.body,g,0,0,s*-.18);
      bolt(s*(torsoW+.08),1.58,-.18,.016,mats.steel,g);
    }

    // arms
    for(const s of [-1,1]){
      const arm=group(g,s*(torsoW+.11),1.63,-.01); arms.push({part:arm,s});
      ell(0,-.04,0,.15,.18,.17,mats.secondary,arm,10);
      plate(0,-.06,-.09,.19,.17,.07,mats.trim,arm,.1,0,0);
      ell(0,-.28,0,.12,.27,.13,mats.body,arm,10);
      plate(0,-.28,-.10,.14,.28,.06,mats.steel3,arm,.08,0,0);
      ell(0,-.53,0,.11,.23,.12,mats.body,arm,10);
      plate(0,-.54,-.09,.13,.14,.05,mats.trim,arm);
      plate(0,-.66,-.09,.16,.08,.05,mats.steel,arm);
      ell(0,-.74,-.01,.10,.12,.11,mats.skin,arm,8);
    }

    // accessories to differentiate classes
    if(d.id==='captain'){
      plate(0,1.58,-.21,.18,.06,.03,mats.gold,g); spritePlane(g,headTex,.12,.14,.10,2.08,-.28,0,0,1); const eye=plate(.09,2.07,-.29,.05,.08,.02,mats.blue,g); makeLensCable();
      const cape=group(g,0,1.20,.32); plate(0,0,0,.54,.80,.03,mats.secondary,cape,.08,0,0); plate(0,-.28,.01,.42,.24,.03,mats.trim,cape,.08,0,0);
      function makeLensCable(){ beam([.11,2.05,-.25],[.20,2.10,-.10],.01,mats.steel2,g); }
    } else if(d.id==='pilot'){
      for(const s of [-1,1]){ ell(s*.30,2.06,-.02,.05,.14,.07,mats.steel3,g,8); ell(s*.31,2.05,-.04,.024,.065,.05,mats.blue,g,8);} ring(0,2.12,.03,.29,.016,mats.steel3,g,0,0,Math.PI);
      const pad=group(g,-.45,1.10,-.28); pad.rotation.z=.18; plate(0,0,0,.28,.42,.05,mats.steel3,pad); plate(0,0,-.025,.21,.31,.02,mats.blue,pad);
    } else if(d.id==='engineer'){
      const rifle=group(g,.60,1.40,.24); rifle.rotation.z=-.72; rifle.rotation.x=.22; beam([0,-.46,0],[0,.30,0],.05,mats.steel3,rifle); plate(0,.36,0,.18,.18,.14,mats.steel3,rifle); plate(0,.46,-.03,.14,.18,.10,mats.blue,rifle); plate(.06,-.16,-.04,.10,.24,.13,mats.black,rifle);
      plate(-.24,1.28,-.20,.10,.16,.04,mats.red,g); plate(.24,1.28,-.20,.10,.16,.04,mats.red,g);
    } else if(d.id==='medic'){
      plate(.29,1.66,-.18,.16,.16,.04,mats.red,g,0,0,.2); plate(.29,1.66,-.20,.07,.07,.02,mats.ivory,g); plate(.26,1.53,.17,.12,.20,.11,mats.red,g);
    } else if(d.id==='security'){
      for(const s of [-1,1]){ const horn=cyl(s*.18,2.28,.02,.012,.05,.28,mats.ivory,g,8); horn.rotation.z=-s*.34; }
      const ringSet=group(g,.44,1.50,-.40); for(let i=0;i<3;i++){ const r=ring(0,0,0,.12+i*.05,.007,mats.blue,ringSet,i*.45,.6*i,0); fx.push(r);} ell(0,0,0,.04,.04,.04,mats.accent,ringSet,8);
    } else if(d.id==='navigator'){
      const goggles=group(g,-.46,1.70,.16); ring(0,0,0,.08,.012,mats.gold,goggles); beam([-.14,0,0],[.14,0,0],.012,mats.gold,goggles);
      const tool=group(g,.47,1.18,-.36); tool.rotation.z=-.25; plate(0,0,0,.14,.54,.10,mats.steel3,tool); plate(0,.18,-.04,.08,.20,.04,mats.amber,tool);
    } else if(d.id==='scientist'){
      plate(0,1.18,-.21,.58,.16,.08,mats.strap,g); for(const s of [-1,1]) plate(s*.17,1.53,-.12,.16,.42,.11,mats.strap,g,0,0,s*.18); plate(0,1.58,-.08,.34,.10,.12,mats.strap,g,.2,0,0);
      const pack=group(g,.42,1.04,-.32); pack.rotation.z=-.14; plate(0,0,0,.24,.32,.16,mats.steel3,pack); plate(0,0,-.09,.15,.15,.02,mats.amber,pack);
    } else if(d.id==='comms'){
      const orb=group(g,.58,1.48,-.43); ell(0,0,0,.05,.05,.05,mats.accent,orb,8); for(let i=0;i<3;i++){ const r=ring(0,0,0,.14+i*.06,.008,mats.purple,orb,i*.4+.2,i*.7,0); fx.push(r);} beam([.18,1.61,.22],[.38,1.69,.28],.012,mats.purple,g); beam([.38,1.69,.28],[.56,1.48,-.30],.012,mats.purple,g);
    } else if(d.id==='mechanic'){
      const deck=group(g,.43,1.10,-.33); deck.rotation.y=.25; plate(0,0,0,.46,.32,.04,mats.lime,deck); plate(0,0,-.024,.37,.24,.02,mats.black,deck); ring(0,.01,-.03,.09,.01,mats.lime,deck);
      const rig=group(g,-.46,1.54,.12); beam([0,-.40,0],[0,.30,0],.04,mats.steel2,rig); beam([0,.26,0],[-.18,.46,0],.05,mats.steel,rig); beam([0,.26,0],[.18,.46,0],.05,mats.steel,rig); ell(0,-.36,0,.12,.10,.10,mats.black,rig,8);
    } else if(d.id==='cadet'){
      for(const s of [-1,1]){ const horn=cyl(s*.20,2.29,.02,.016,.07,.34,mats.strap,g,8); horn.rotation.z=-s*.55; }
      const spikes=group(g,0,1.80,.22); for(const s of [-1,1]) for(let i=0;i<3;i++) plate(s*(.10+i*.12),-.15*i,0,.05,.16,.06,mats.red,spikes,-.55,0,s*-.3);
    }

    return {root,visual:g,arms,legs,name:d.name,role:d.role,index:CREW.findIndex(c=>c.id===d.id),fx,head:torsoGroup};
  };
})();

/**
 * NAVESTAR — COMUNICAÇÕES / CHARACTER 08
 * Modelagem 3D procedural com textura original do retrato (rosto CURVO 3D).
 * Version: 2026.10.15 — Three.js r150+ (THREE global)
 *
 * INSTALAÇÃO NO JOGO
 * 1. Mantenha o arquivo original de avatares no projeto.
 * 2. Carregue ESTE arquivo DEPOIS do arquivo original.
 *    <script src="js/avatar_comunicacoes_3d_ultra.js"></script>
 * 3. O avatar index=7 (Comunicações) passa a usar esta versão automaticamente.
 * 4. Os outros 9 avatares permanecem exatamente como no arquivo original.
 *
 * Também pode chamar:
 *   const avatar = NaveStarComms3D.create(THREE, scene);
 *   avatar.update(performance.now() * 0.001);
 *
 * Demo independente (com Three.js já carregado):
 *   NaveStarComms3D.mount(document.getElementById('viewer'));
 *
 * Sem arquivos de textura externos. O rosto original é incorporado abaixo.
 */
(function (global) {
  'use strict';
  const PREVIOUS_CREATOR = typeof global.createCrewAvatarModel === 'function'
    ? global.createCrewAvatarModel : null;
  const VERSION='2026.10.15-PBR-ULTIMATE-1MB';
  const PORTRAIT_SRC = 'data:image/webp;base64,';

  // Atlas físicos EMBUTIDOS, cada pixel altera de verdade o acabamento 3D.
  // Independente de recursos externos. Texturas reais: albedo, normal, roughness, pele.
  const MATERIAL_BASE_DATA = 'data:image/webp;base64,';
  const MATERIAL_NORMAL_DATA = 'data:image/webp;base64,';
  const MATERIAL_ROUGHNESS_DATA = 'data:image/webp;base64,';
  const FACE_NORMAL_DATA = 'data:image/webp;base64,';
  function loadPBRTexture(THREE,src,repeat=1,srgb=false){
    const t=new THREE.TextureLoader().load(src);
    t.wrapS=t.wrapT=THREE.RepeatWrapping;
    t.repeat.set(repeat,repeat);
    t.anisotropy=8;
    if(srgb && THREE.SRGBColorSpace)t.colorSpace=THREE.SRGBColorSpace;
    t.needsUpdate=true;
    return t;
  }

  const CREW_INDEX=7;
  const pi=Math.PI;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function randomSeed(seed){let s=seed>>>0;return ()=>((s=(s*1664525+1013904223)>>>0)/4294967296);}

  function create(THREE,parent,opts={}){
    if(!THREE || !THREE.Mesh || !THREE.Group){throw new Error('Three.js não carregado — carregue THREE antes deste arquivo.');}
    const rand=randomSeed(508822);
    const root=new THREE.Group();
    root.name='NaveStar / Comunicações / avatar-08';
    parent?.add(root);
    const visual=new THREE.Group(); root.add(visual);
    const female=new THREE.Group(); visual.add(female);
    female.scale.setScalar(opts.scale ?? 0.525); // altura compatível com a família original (≈2,4)
    const arms=[],legs=[],fx=[],animatedBraids=[];
    const geomCache=new Map();

    // Materiais PBR verdadeiros — não há planos de busto ou corpo 2D.
    const mat=(color,metal=.55,rough=.38,more={})=>new THREE.MeshStandardMaterial({
      color,metalness:metal,roughness:rough, ...more
    });
    const glow=(color,intensity=1.6)=>mat(color,.30,.22,{emissive:color,emissiveIntensity:intensity});
    const M={
      skin:mat(0x9868c5,.05,.68),
      skinLight:mat(0xbc80e2,.02,.63),
      lips:mat(0x673675,.15,.34),
      hair:mat(0x170d24,.15,.55),
      hair2:mat(0x2d153d,.24,.38),
      hair3:mat(0x481852,.30,.34),
      hairLight:mat(0x76328e,.36,.30),
      graphite:mat(0x14131d,.78,.32),
      flex:mat(0x100f19,.10,.82),
      graphite2:mat(0x292330,.68,.30),
      carapace:mat(0x35273f,.78,.22),
      alloy:mat(0x4a4455,.88,.23),
      alloyBright:mat(0x7e758c,.94,.19),
      alloyDark:mat(0x211f29,.81,.31),
      titanium:mat(0x6b6480,.92,.26),
      purpleMetal:mat(0x54326f,.75,.27),
      detail:mat(0x9886a3,.82,.27),
      violet:glow(0xbe55ff,2.3),
      magenta:glow(0xed65ff,2.3),
      violetDim:glow(0x7f38cb,.85),
      cyan:glow(0x57e8ff,2.45),
      ice:glow(0xa6fbff,2.6),
      eye:glow(0x7dfbff,3.5),
      seam:mat(0x32243e,.22,.62),
      inner:mat(0x090b10,.32,.57),
      rivet:mat(0xc3bacc,.95,.20)
    };


    // A armadura usa os três mapas PBR simultaneamente. As ranhuras,
    // parafusos, linhas de usinagem e micro-riscos mudam os reflexos sob luz.
    const armorBase=loadPBRTexture(THREE,MATERIAL_BASE_DATA,1.8,true);
    const armorNormal=loadPBRTexture(THREE,MATERIAL_NORMAL_DATA,1.8,false);
    const armorRough=loadPBRTexture(THREE,MATERIAL_ROUGHNESS_DATA,1.8,false);
    const skinNormal=loadPBRTexture(THREE,FACE_NORMAL_DATA,1,false);
    [M.carapace,M.alloy,M.graphite2,M.alloyDark,M.titanium,M.purpleMetal,M.graphite].forEach((m,i)=>{
      m.map=armorBase;
      m.normalMap=armorNormal;
      m.roughnessMap=armorRough;
      m.normalScale=new THREE.Vector2(i===0?.26:.14,i===0?.26:.14);
      m.needsUpdate=true;
    });

    function mesh(geo, material, parent=female, x=0,y=0,z=0){
      const ob=new THREE.Mesh(geo,material);ob.position.set(x,y,z);
      ob.castShadow=true;ob.receiveShadow=true;parent.add(ob);return ob;
    }
    function group(parent=female,x=0,y=0,z=0){const ob=new THREE.Group();ob.position.set(x,y,z);parent.add(ob);return ob;}
    function sphere(x,y,z,a,b,c,material,parent=female,detail=28){
      let geo=geomCache.get('s:'+detail);
      if(!geo){geo=new THREE.SphereGeometry(1,detail,Math.max(16,Math.floor(detail*.7)));geomCache.set('s:'+detail,geo);}
      const ob=mesh(geo,material,parent,x,y,z);ob.scale.set(a,b,c);return ob;
    }
    function cuboid(x,y,z,a,b,c,material,parent=female,bevel=0){
      const geo=new THREE.BoxGeometry(a,b,c); const ob=mesh(geo,material,parent,x,y,z);
      return ob;
    }
    function cylinder(x,y,z,top,bottom,height,material,parent=female,seg=20){
      return mesh(new THREE.CylinderGeometry(top,bottom,height,seg),material,parent,x,y,z);
    }
    function torus(x,y,z,r,t,material,parent=female,rx=0,ry=0,rz=0){
      const ob=mesh(new THREE.TorusGeometry(r,t,9,42),material,parent,x,y,z);ob.rotation.set(rx,ry,rz);return ob;
    }
    function pointsToVectors(points){return points.map(p=>new THREE.Vector3(...p));}
    function path(points,r,material,parent=female,segments=30,tubular=7){
      if(points.length<2)return null;
      const curve=new THREE.CatmullRomCurve3(pointsToVectors(points),false,'centripetal');
      const o=mesh(new THREE.TubeGeometry(curve,segments,r,tubular,false),material,parent);return o;
    }
    function line(a,b,r,material,parent=female){
      const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),dir=bv.clone().sub(av);
      const o=mesh(new THREE.CylinderGeometry(r,r,dir.length(),9),material,parent,...av.clone().add(bv).multiplyScalar(.5).toArray());
      o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());return o;
    }
    function hexBolt(x,y,z,r,parent=female){
      const b=cylinder(x,y,z,r,r,.022,M.rivet,parent,6);b.rotation.x=pi/2;
      const slot=cuboid(x,y,z-.015,r*1.2,.009,.007,M.alloyDark,parent);return [b,slot];
    }
    function polygon(verts,z,thickness,material,parent=female,bevel=.015){
      const s=new THREE.Shape(); verts.forEach(([x,y],i)=>i?s.lineTo(x,y):s.moveTo(x,y));s.closePath();
      const geometry=new THREE.ExtrudeGeometry(s,{depth:thickness,bevelEnabled:bevel>0,
        bevelSegments:3,steps:1,bevelThickness:bevel,bevelSize:bevel,curveSegments:12});
      const o=mesh(geometry,material,parent,0,0,z);return o;
    }
    function plateOutline(verts,z,color,parent=female,r=.009){
      const points=verts.map(([x,y])=>[x,y,z]);points.push([verts[0][0],verts[0][1],z]);path(points,r,color,parent,verts.length*6,6);
    }

    // Anatomia articulável. Superfícies convexas por baixo de placas esculpidas.
    sphere(0,2.28,.055,.46,.30,.29,M.flex);
    sphere(0,2.78,.06,.54,.74,.31,M.graphite);
    sphere(0,2.97,-.05,.53,.54,.29,M.graphite2);
    sphere(0,1.94,.015,.39,.27,.26,M.graphite);
    // cintura revestida, costelas em relevo e juntas
    for(let i=0;i<6;i++){
      const y=2.12+i*.12;
      torus(0,y,-.015,.29+(i*.026),.017,i%2?M.alloyDark:M.graphite2,female,pi/2,0,0);
    }
    for(const s of [-1,1]){
      const gl=group(female,s*.24,1.94,0);
      const thigh=sphere(0,-.39,.01,.23,.57,.23,M.flex,gl);
      const lower=group(gl,0,-.82,0);legs.push({part:gl,s,lower});
      sphere(0,-.05,-.03,.22,.22,.22,M.graphite2,lower);
      sphere(0,-.39,.015,.19,.35,.19,M.flex,lower);
      sphere(0,-.72,-.035,.21,.17,.21,M.graphite,lower);
      sphere(0,-.80,-.16,.225,.145,.39,M.graphite,lower);
      polygon([[-.18,-.16],[.19,-.16],[.20,-.48],[.12,-.74],[-.12,-.74],[-.21,-.47]],-.225,.046,M.carapace,lower,.02);
      polygon([[-.105,-.25],[.11,-.25],[.08,-.57],[-.08,-.57]],-.287,.01,M.purpleMetal,lower,.01);
      path([[-.06,-.29,-.304],[0,-.38,-.31],[.06,-.48,-.304]],.012,M.violet,lower);
      for(let j=0;j<4;j++){
        const y=-.24-j*.12;
        const x=.20+j*.004;
        line([s*.01?x:x,y,.12],[x+.03,y-.04,.0],.013,M.alloy,lower);
      }
      // fêmur: placas articuladas blindadas + articulação do joelho
      polygon([[-.185,-.03],[.18,-.03],[.22,-.28],[.15,-.62],[-.16,-.62],[-.21,-.28]],-.24,.058,M.graphite2,gl,.022);
      polygon([[-.13,-.12],[.14,-.12],[.16,-.34],[.04,-.49],[-.08,-.39]],-.309,.013,M.carapace,gl,.01);
      path([[-.12,-.13,-.33],[.12,-.13,-.33],[.15,-.32,-.32]],.012,M.violetDim,gl,14);
      for(let j=0;j<3;j++){cuboid(s*.18,-.23-j*.15,-.18,.095,.034,.09,M.titanium,gl);}
    }

    // Cinto utilitário + cilindros acoplados + centenas de microdetalhes.
    sphere(0,2.08,-.006,.43,.12,.29,M.graphite);
    torus(0,2.04,-.02,.31,.023,M.titanium,female,pi/2);
    cuboid(0,2.065,-.303,.23,.15,.05,M.alloy);
    cuboid(0,2.066,-.345,.10,.038,.014,M.violet);
    for(const s of [-1,1]){
      for(let j=0;j<3;j++){
        const x=s*(.23+j*.087);
        cuboid(x,2.10,-.256,.075,.13,.09,j%2?M.graphite2:M.alloyDark);
        cuboid(x,2.155,-.309,.044,.013,.015,M.titanium);
      }
      for(let k=0;k<4;k++){
        const a=(k/3)*pi*.70 +.20;
        cuboid(s*.4,1.94+k*.06,.09,.05,.03,.09,M.alloyDark);
      }
    }

    // Costas e coluna de energia: esta peça é 3D e aparece quando o jogador gira.
    sphere(0,2.82,.285,.32,.61,.15,M.graphite2);
    polygon([[-.29,3.34],[.29,3.34],[.33,2.65],[.11,2.34],[-.11,2.34],[-.33,2.65]],.32,.065,M.alloyDark);
    for(let i=0;i<8;i++){
      const yy=2.43+i*.105;
      cuboid(0,yy,.402,.15,.025,.042,i%2?M.alloyBright:M.graphite2);
      sphere(0,yy,.432,.025,.019,.015,i%3===0?M.violet:M.titanium);
    }
    for(const s of [-1,1]){
      const x=s*.33;
      const p=group(female,x,2.97,.31);
      sphere(0,0,0,.14,.26,.12,M.alloyDark,p);
      for(let j=0;j<3;j++)torus(0,-.13+j*.13,.05,.12,.014,j===1?M.violetDim:M.titanium,p,pi/2);
    }

    // Peitoral: peças convexas, anatomia, chanfros, bordas e trilhas luminosas.
    for(const s of [-1,1]){
      sphere(s*.225,2.94,-.17,.275,.37,.27,M.carapace);
      // camadas de fibra reforçada
      polygon([[s*.05,3.34],[s*.30,3.38],[s*.48,3.22],[s*.50,2.98],[s*.36,2.69],[s*.08,2.74]],-.346,.07,M.alloyDark,female,.022);
      polygon([[s*.075,3.26],[s*.29,3.30],[s*.43,3.17],[s*.415,2.98],[s*.325,2.81],[s*.095,2.83]],-.420,.05,M.carapace,female,.017);
      polygon([[s*.14,3.14],[s*.28,3.19],[s*.36,3.12],[s*.30,2.98],[s*.18,3.01]],-.493,.013,M.alloy,female,.01);
      // fita LED principal do peito, mesmo desenho angular do retrato
      path([[s*.10,3.32,-.457],[s*.22,3.29,-.472],[s*.30,3.20,-.482],[s*.32,3.05,-.493]],.020,M.violet,female,30);
      path([[s*.17,2.90,-.491],[s*.30,2.79,-.482],[s*.41,2.81,-.451]],.013,M.magenta,female,24);
      path([[s*.06,3.35,-.41],[s*.31,3.40,-.35],[s*.48,3.23,-.36]],.013,M.titanium,female);
      hexBolt(s*.43,3.26,-.42,.026);hexBolt(s*.38,2.80,-.46,.025);
    }
    polygon([[-.09,3.35],[.09,3.35],[.13,2.76],[0,2.68],[-.13,2.76]],-.39,.085,M.graphite);
    polygon([[-.062,3.19],[.062,3.19],[.08,2.85],[0,2.78],[-.08,2.85]],-.48,.015,M.purpleMetal);
    path([[0,3.24,-.50],[0,3.04,-.51],[0,2.84,-.50]],.012,M.violet);
    sphere(0,2.94,-.523,.045,.065,.017,M.violet);
    for(let i=0;i<7;i++){
      const y=2.41+i*.073;
      const w=.33+i*.013;
      path([[-w,y,-.276],[0,y+.012,-.340],[w,y,-.276]],.009,i%2?M.alloy:M.violetDim);
    }

    // Pescoço alto e gola protetora repartida em segmentos.
    cylinder(0,3.53,.005,.145,.18,.36,M.flex);
    for(let i=0;i<5;i++) torus(0,3.41+i*.06,-.002,.165,.012,i%2?M.titanium:M.alloyDark,female,pi/2);
    for(const s of [-1,1]){
      polygon([[s*.08,3.60],[s*.30,3.65],[s*.45,3.45],[s*.36,3.31],[s*.13,3.41]],-.19,.08,M.graphite2,female,.025);
      polygon([[s*.15,3.58],[s*.29,3.60],[s*.38,3.46],[s*.30,3.39]],-.278,.014,M.alloyDark,female,.009);
      path([[s*.19,3.55,-.30],[s*.30,3.53,-.30],[s*.34,3.46,-.30]],.011,M.violetDim);
      hexBolt(s*.27,3.48,-.30,.02);
    }

    // Ombreiras e braços — juntas independentes, placas sobrepostas, microparafusos.
    for(const s of [-1,1]){
      const arm=group(female,s*.605,3.28,0);arms.push({part:arm,s});
      sphere(0,0,0,.23,.28,.24,M.flex,arm);
      sphere(s*.067,-.12,-.04,.245,.29,.24,M.graphite2,arm);
      // ombreira convexa e casca com borda segmentada
      sphere(s*.054,.07,-.052,.32,.23,.27,M.alloyDark,arm);
      sphere(s*.055,.085,-.140,.27,.20,.15,M.carapace,arm);
      polygon([[s*-.20,.12],[s*.16,.22],[s*.31,.13],[s*.32,-.06],[s*.19,-.19],[s*-.18,-.09]],-.292,.045,M.graphite2,arm,.025);
      polygon([[s*-.17,.12],[s*.15,.20],[s*.255,.10],[s*.235,-.035],[s*.15,-.12],[s*-.14,-.045]],-.342,.016,M.purpleMetal,arm,.012);
      // forma pontiaguda em violeta na parte superior
      path([[s*-.15,.15,-.361],[s*.02,.16,-.371],[s*.21,.085,-.37]],.026,M.magenta,arm,24);
      path([[s*-.13,-.03,-.368],[s*.05,-.085,-.37],[s*.19,-.13,-.35]],.014,M.violetDim,arm,21);
      hexBolt(s*.18,-.095,-.378,.029,arm);
      // antebraço
      sphere(s*.045,-.42,0,.175,.32,.18,M.flex,arm);
      sphere(s*.025,-.58,-.09,.166,.27,.15,M.graphite2,arm);
      const fore=group(arm,s*.02,-.67,0);
      polygon([[-.16,.20],[.16,.20],[.19,-.20],[.08,-.38],[-.08,-.38],[-.19,-.20]],-.245,.06,M.carapace,fore,.026);
      polygon([[-.12,.14],[.12,.14],[.13,-.17],[0,-.30],[-.13,-.17]],-.313,.018,M.alloyDark,fore,.01);
      path([[-.08,.16,-.339],[.07,.14,-.339],[.105,-.13,-.344]],.017,M.violet,fore);
      path([[0,.045,-.345],[0,-.15,-.345]],.009,M.magenta,fore);
      for(let k=0;k<4;k++)cuboid(s*.14,-.10-k*.077,-.05,.047,.037,.035,M.titanium,fore);
      // Mão, dedos e juntas
      sphere(0,-.43,-.02,.115,.15,.095,M.graphite,fore);
      for(let finger=0;finger<4;finger++){
        const xx=(finger-1.5)*.057;
        line([xx,-.51,-.018],[xx,-.64+(finger===3?.045:0),-.035],.018,M.graphite,fore);
        sphere(xx,-.62+(finger===3?.045:0),-.036,.020,.020,.021,M.titanium,fore,16);
      }
      sphere(s*.095,-.54,-.095,.038,.080,.047,M.graphite,fore);
      // Faixas do bíceps
      torus(s*.025,-.36,-.02,.165,.016,M.titanium,arm,pi/2);
      torus(s*.025,-.44,-.02,.162,.012,M.violetDim,arm,pi/2);
    }

    // Cabeça com volume, plano facial anatomicamente CURVADO e textura ORIGINAL da personagem.
    const head=group(female,0,3.84,-.045);
    // crânio, nuca, mandíbula e orelhas modelados em volumes.
    sphere(0,.124,.030,.337,.43,.316,M.skin,head,50);
    sphere(0,-.204,-.003,.255,.17,.216,M.skin,head,42);
    sphere(0,-.245,-.14,.125,.092,.116,M.skinLight,head,32); // queixo
    for(const s of [-1,1]){
      sphere(s*.319,-.006,-.023,.087,.158,.067,M.skin,head,40);
      sphere(s*.343,-.005,-.070,.04,.090,.027,M.skinLight,head,24);
      torus(s*.355,-.072,-.091,.023,.007,M.alloyBright,head,0,s*.25);
      sphere(s*.353,-.14,-.10,.021,.028,.018,M.violet,head);
      path([[s*.35,-.14,-.10],[s*.38,-.22,-.09],[s*.43,-.29,-.06]],.008,M.titanium,head);
    }
    // superfície personalizada: forma do maxilar, maçãs do rosto e projeção do nariz.
    function faceAt(u,v,extra=0){
      const vy=v*2-1; const t=(vy+1)*.5;
      const width=.285*(.79 + .19*Math.cos(vy*2.3) - .12*(1-t));
      const xx=(u*2-1)*width;
      const ny=(t*.735)-.31;
      const taper=Math.sqrt(Math.max(0.02,1-Math.pow(u*2-1,2)));
      const z=-.115-.218*taper;
      const nose=Math.exp(-Math.pow((u-.65)/.10,2)-Math.pow((v-.46)/.13,2))*.092;
      const cheeks=(Math.exp(-Math.pow((u-.26)/.16,2)-Math.pow((v-.43)/.20,2))+
       Math.exp(-Math.pow((u-.79)/.14,2)-Math.pow((v-.43)/.20,2)))*.015;
      const muzzle=Math.exp(-Math.pow((u-.58)/.19,2)-Math.pow((v-.25)/.11,2))*.020;
      return [xx,ny,z-nose-cheeks-muzzle-extra];
    }
    const Nx=132,Ny=144,position=[],uv=[],normals=[],indexArr=[];
    for(let iy=0;iy<=Ny;iy++)for(let ix=0;ix<=Nx;ix++){
      const u=ix/Nx,v=iy/Ny;position.push(...faceAt(u,v,0));uv.push(u,v);
    }
    for(let iy=0;iy<Ny;iy++)for(let ix=0;ix<Nx;ix++){
      const a=iy*(Nx+1)+ix,b=a+1,c=a+Nx+1,d=c+1;
      // frente do personagem aponta para -Z
      indexArr.push(a,c,b,b,c,d);
    }
    const faceGeo=new THREE.BufferGeometry();
    faceGeo.setAttribute('position',new THREE.Float32BufferAttribute(position,3));
    faceGeo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
    faceGeo.setIndex(indexArr);faceGeo.computeVertexNormals();
    const faceCanvas=document.createElement('canvas');faceCanvas.width=1024;faceCanvas.height=1024;
    const fc=faceCanvas.getContext('2d',{willReadFrequently:true});
    const baseTex=new THREE.CanvasTexture(faceCanvas);baseTex.colorSpace=THREE.SRGBColorSpace;
    baseTex.anisotropy=Math.min(8,THREE?.capabilities?.getMaxAnisotropy?.()||8);
    const glowCanvas=document.createElement('canvas');glowCanvas.width=1024;glowCanvas.height=1024;
    const ec=glowCanvas.getContext('2d');const emission=new THREE.CanvasTexture(glowCanvas);
    const faceMaterial=new THREE.MeshStandardMaterial({
      color:0xffffff,map:baseTex,transparent:true,alphaTest:.05,depthWrite:true,
      metalness:.02,roughness:.57,normalMap:skinNormal,normalScale:new THREE.Vector2(.20,.20),emissive:0x43b6f8,emissiveMap:emission,emissiveIntensity:1.05,
      side:THREE.DoubleSide
    });
    mesh(faceGeo,faceMaterial,head);
    const portrait=new Image();portrait.decoding='async';
    portrait.onload=()=>{
      // região do ROSTO do retrato original 460x460; sem o corpo impresso em planos.
      fc.clearRect(0,0,1024,1024);
      fc.drawImage(portrait,184*portrait.width/460,48*portrait.height/460,183*portrait.width/460,221*portrait.height/460,0,0,1024,1024);
      let pixels=fc.getImageData(0,0,512,512);const D=pixels.data;
      // máscara macia suaviza a transição do rosto fotográfico para o crânio físico.
      for(let y=0;y<1024;y++)for(let x=0;x<1024;x++){
        const i=4*(y*1024+x);const sx=(x-514)/502,sy=(y-502)/514;
        const edge=Math.sqrt(sx*sx*.98+sy*sy*.92);
        let a=clamp((1.045-edge)/.16,0,1);
        // laterais do queixo e linha do cabelo fundem-se com o material violeta.
        a*=clamp((x+20)/80,0,1)*clamp((1050-x)/92,0,1);
        D[i+3]=Math.round(255*a);
      }
      fc.putImageData(pixels,0,0);baseTex.needsUpdate=true;
      // extração de emissão de regiões azul/ciano do próprio retrato.
      const em=ec.createImageData(1024,1024);const E=em.data;
      for(let i=0;i<D.length;i+=4){
        const R=D[i],G=D[i+1],B=D[i+2];
        const cyan=clamp(((B-R)*.016+(G-R)*.008-.55),0,1);
        E[i]=Math.round(90*cyan);E[i+1]=Math.round(210*cyan);
        E[i+2]=Math.round(255*cyan);E[i+3]=255;
      }
      ec.putImageData(em,0,0);emission.needsUpdate=true;
    };
    portrait.src=PORTRAIT_SRC;

    // Marcas tecnológicas em geometria REAL, acompanhando a curvatura do rosto.
    function mapReference(x,y,extrude=.007){
      const u=clamp((x-184)/183,0.01,.99),v=clamp(1-(y-48)/221,.01,.99);
      return faceAt(u,v,extrude);
    }
    const circuitLines=[
      [[274,63],[275,74],[284,86],[283,96],[288,105]],
      [[217,148],[211,159],[226,170],[229,183],[222,194],[233,208]],
      [[240,181],[244,191],[252,198],[254,210]],
      [[275,96],[280,101],[294,113]],
      [[263,207],[267,215],[279,219]]
    ];
    circuitLines.forEach((ln,i)=>{
      const p=ln.map(([x,y])=>mapReference(x,y,.014));
      path(p,.0042,i%3?M.cyan:M.ice,head,26,8);
      for(const pos of [p[1],p[p.length-2]])sphere(...pos,.009,.009,.009,M.cyan,head,12);
    });
    // reflexos adicionais nos olhos, sem apagar o retrato.
    for(const [ex,ey] of [[273,130],[323,134]]){
      const p=mapReference(ex,ey,.02);
      sphere(p[0],p[1],p[2],.013,.006,.003,M.eye,head,18);
    }

    // Hairline crescida e traças individualizadas: mais de 50 locks de curvatura orgânica.
    sphere(0,.355,.105,.35,.255,.30,M.hair,head,48);
    for(let k=0;k<13;k++){
      const t=k/12,xx=-.30+t*.60;
      const cy=.35 + .10*Math.sin(t*pi);
      path([[xx,cy,.00],[xx*.92,cy+.075,-.02],[xx*.80,cy+.15,.08]],.013+(k%4)*.002,
        k%3?M.hair3:M.hair2,head,18);
    }
    for(let k=0;k<62;k++){
      const layer=Math.floor(k/22),j=k%22;
      const ang=-.14+(j/21)*pi*1.98+(rand()-.5)*.20;
      // scalp roots: cabelo afastado da face, maior volume para trás e nas laterais.
      const rad=.20+.11*rand();
      const sx=Math.sin(ang)*rad, sz=Math.cos(ang)*rad*.85+.06;
      const sy=.41+(.08*rand())-.045*layer;
      const side=Math.sign(sx)||1;
      const spread=(.02+rand()*.22)*(sz<0?.6:1);
      const len=.63+rand()*.84+(layer*.12);
      const pts=[
        [sx*.68,sy+.08,sz*.68],
        [sx*1.05,sy+.17,sz],
        [sx*1.23+side*.025,sy+.06,sz+.035],
        [sx*1.34+side*spread,sy-.27,sz+(.07+rand()*.12)],
        [sx*1.55+side*spread,sy-len*.65,sz+(.11+rand()*.12)],
        [sx*1.61+side*spread*.75,sy-len,sz+.11]
      ];
      // distribuir dreadlocks: alguns caem sobre peito e ombros, outros nas costas
      if((k%7===0||k%11===0)&&Math.abs(sx)>.14){
        pts[3][2]-=.17;pts[4][2]-=.37;pts[5][2]-=.38;
      }
      const radius=.016+(k%8)*.0018;
      const braid=group(head);
      path(pts,radius,[M.hair,M.hair2,M.hair3][k%3],braid,42,8);
      // cordas helicoidais em cima das mechas — seções visíveis à curta distância.
      if(k%3!==0){
        const curve=new THREE.CatmullRomCurve3(pointsToVectors(pts));
        const pts1=[],pts2=[];let vec;
        for(let it=0;it<=75;it++){
          const t=it/75; const center=curve.getPoint(t),tangent=curve.getTangent(t);
          vec=new THREE.Vector3(1,0,.2).cross(tangent).normalize();
          const sec=new THREE.Vector3().crossVectors(tangent,vec).normalize();
          const a=t*pi*2*(18+k%6);
          pts1.push(center.clone().addScaledVector(vec,Math.cos(a)*(radius+.0015)).addScaledVector(sec,Math.sin(a)*(radius+.0015)).toArray());
          if(k%5===0)pts2.push(center.clone().addScaledVector(vec,-Math.cos(a)*(radius+.001)).addScaledVector(sec,-Math.sin(a)*(radius+.001)).toArray());
        }
        path(pts1,.0035,k%9?M.hairLight:M.violetDim,braid,96,5);
        if(pts2.length)path(pts2,.0022,M.hair3,braid,96,5);
      }
      if(k%6===0){
        const curve=new THREE.CatmullRomCurve3(pointsToVectors(pts));
        for(const t of [.23,.48,.69]){
          const q=curve.getPoint(t),tg=curve.getTangent(t);
          const bead=torus(...q.toArray(),radius+.005,.006,k%12?M.titanium:M.violet,braid);
          bead.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),tg.normalize());
        }
      }
      if(k%4===0)animatedBraids.push({part:braid,phase:rand()*pi*2,amount:.010+rand()*.010});
    }
    // dreadlocks caindo à frente da armadura (fora do rosto)
    for(const side of [-1,1])for(let i=0;i<8;i++){
      const sx=side*(.25+i*.017),endX=side*(.35+i*.046), y0=.14-i*.017;
      const points=[[sx,.34,.025],[sx+side*.045,.10,-.19],[sx+side*.09,-.27,-.31],
        [endX,-.69,-.42],[endX+side*.05,-1.17-(i%3)*.10,-.40]];
      path(points,.014+(i%4)*.003,i%3===0?M.hairLight:M.hair2,head,46);
      if(i%2===0)path(points.map((p,j)=>[p[0]+side*.008,p[1],p[2]-.008]),.0028,M.hairLight,head,46);
    }

    // Auriculares e interface de rádio orbital (parte da roupa, não figura plana).
    for(const s of [-1,1]){
      sphere(s*.345,.035,.055,.080,.14,.08,M.alloyDark,head);
      torus(s*.376,.036,-.001,.071,.018,M.alloyBright,head,0,s*.2);
      torus(s*.380,.038,-.041,.046,.009,M.violet,head,0,s*.20);
      sphere(s*.377,.033,-.065,.020,.029,.014,M.ice,head);
      path([[s*.39,.01,.02],[s*.41,-.14,.03],[s*.36,-.27,-.11]],.010,M.purpleMetal,head);
    }

    // transmissor pequeno perto do ombro (setor Comunicações)
    const radio=group(female,.58,3.28,.06);
    cylinder(0,.05,0,.075,.093,.19,M.alloyDark,radio,10);
    cylinder(0,.16,0,.016,.027,.16,M.titanium,radio,12);
    sphere(0,.25,0,.03,.03,.03,M.cyan,radio);
    torus(0,.06,-.12,.09,.01,M.violet,radio,0,.4);
    for(let i=0;i<4;i++){
      const yy=3.45+i*.095;
      path([[.54,yy,-.22],[.69,yy+.02,-.19],[.77,yy+.06,-.06]],.005,M.cyan,female,14);
    }
    // Interface holo opcional, com aneis 3D de rádio que podem ser animados.
    const hologram=group(female,.90,2.81,-.68);
    hologram.visible=opts.showHologram!==false;
    sphere(0,0,0,.033,.033,.033,M.ice,hologram);
    for(let i=0;i<3;i++){
      const ring=torus(0,0,0,.14+i*.055,.006,i%2?M.cyan:M.violet,hologram,.35+i*.40,i*.50);
      fx.push(ring);
    }
    for(let i=0;i<12;i++){
      const a=i/12*pi*2;
      sphere(Math.sin(a)*.23,Math.cos(a)*.23,0,.010,.010,.010,i%3?M.violet:M.cyan,hologram,12);
    }
    // acabamento: trilhos metálicos, linhas luminosas e serial no peito
    for(const s of [-1,1]){
      for(let i=0;i<8;i++){
        const x=s*(.12+i*.039), y=2.59+.016*(i%2);
        cuboid(x,y,-.357,.023,.011,.018,i%3?M.alloy:M.violetDim);
      }
      for(let i=0;i<5;i++) hexBolt(s*(.27+i*.039),2.24,-.29,.011);
    }
    // back-neck armor is visible behind scalp
    torus(0,3.59,.07,.205,.036,M.graphite2,female,pi/2);


    // 190 detalhes adicionais instanciados: travas, rebites e terminais luminosos.
    // São geometrias 3D visíveis ao girar o avatar, e não uma camada de imagem.
    const microBoltGeo=new THREE.CylinderGeometry(.009,.011,.015,10);
    const microBoltMat=M.rivet;
    const bolts=new THREE.InstancedMesh(microBoltGeo,microBoltMat,190);
    bolts.name='190 microparafusos mecanizados / bancada da tripulação';
    const oDummy=new THREE.Object3D();
    let count=0;
    function microBolt(x,y,z,s=1){
      oDummy.position.set(x,y,z);oDummy.rotation.set(pi/2,0,0);
      oDummy.scale.setScalar(s);oDummy.updateMatrix();bolts.setMatrixAt(count++,oDummy.matrix);
    }
    for(const side of [-1,1]){
      for(let row=0;row<8;row++){
        const yy=2.55+row*.091;
        const xx=side*(.18+row*.026);
        for(let c=0;c<5;c++){
          microBolt(xx+side*c*.034,yy,-.468+row*.011,.62+(row%3)*.14);
        }
      }
      for(let k=0;k<9;k++){
        microBolt(side*(.20+(k%3)*.081),2.31+Math.floor(k/3)*.083,-.302,.55);
      }
    }
    for(let k=0;k<12;k++) microBolt(Math.sin(k*.5)*.27,2.08,-.313,.85);
    while(count<190) microBolt(0,-100,0,.001); // capacidade estável de instancing
    bolts.instanceMatrix.needsUpdate=true;female.add(bolts);
    // Dutos emissores no peitoral: curvas em relevo acompanhando painéis reais
    for(const side of [-1,1]){
      for(let j=0;j<4;j++){
        const y0=2.76+j*.126;
        path([[side*.20,y0,-.497],[side*.27,y0+.032,-.505],[side*.36,y0+.03,-.476]],.0065,j%2?M.violetDim:M.violet,female,30,6);
      }
      for(let k=0;k<7;k++){
        const y0=2.31+k*.105;
        sphere(side*.432,y0,-.24,.015,.017,.015,k%3===0?M.magenta:M.alloyBright,female,14);
      }
    }

    // Todas as geometrias no retorno são rotacionáveis e renderizadas no mundo 3D.
    let t0=0;
    function update(time=0){
      if(!Number.isFinite(time))time=0;
      t0=time;
      // respiração e movimento sutil da cabeça
      visual.position.y=Math.sin(time*1.3)*.008;
      head.rotation.z=Math.sin(time*.61)*.018;
      head.rotation.y=Math.sin(time*.35)*.055-.07;
      for(const o of animatedBraids)o.part.rotation.z=Math.sin(time*.68+o.phase)*o.amount;
      fx.forEach((r,i)=>{r.rotation.x=time*(i%2?-.4:.36)+i*.3;r.rotation.y=time*.35+i*.8;});
      hologram.rotation.y=time*.14;
    }
    update(0);
    root.userData.naveStar={id:'comms',name:'Comunicações',species:'augmented',update,version:VERSION};
    const result={root,visual,arms,legs,fx,head,name:'Comunicações',role:'Operação de sinais',index:CREW_INDEX,update,
      setHologramVisible(v){hologram.visible=!!v;},
      dispose(){
        root.traverse(o=>{if(o.isMesh && o.geometry && !Array.from(geomCache.values()).includes(o.geometry))o.geometry.dispose();});
        [...geomCache.values(),faceGeo].forEach(g=>g.dispose());
        Object.values(M).forEach(m=>m.dispose());faceMaterial.dispose();baseTex.dispose();emission.dispose();armorBase.dispose();armorNormal.dispose();armorRough.dispose();skinNormal.dispose();
        root.parent?.remove(root);
      }
    };
    return result;
  }

  // Compatível com a API anterior, mantendo os 9 personagens intactos.
  global.createCrewAvatarModel=function(THREE,index,parent,helpers){
    const n=Number(index);
    if(n!==CREW_INDEX){
      if(PREVIOUS_CREATOR)return PREVIOUS_CREATOR(THREE,index,parent,helpers);
      throw new Error(`Personagem ${index}: carregue o JS original antes deste aprimoramento.`);
    }
    return create(THREE,parent,{showHologram:true});
  };

  // Visualizador standalone opcional: sem OrbitControls, sem imports ESM.
  function mount(container,opts={}){
    const THREE=opts.THREE || global.THREE;
    if(!THREE)throw new Error('Inclua Three.js antes de usar NaveStarComms3D.mount().');
    if(typeof container==='string')container=document.querySelector(container);
    if(!container)throw new Error('Elemento de destino não encontrado');
    container.style.position='relative';
    const scene=new THREE.Scene();
    scene.background=new THREE.Color(opts.background || '#090a15');
    const camera=new THREE.PerspectiveCamera(31,1,.1,40);
    const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});
    renderer.setPixelRatio(Math.min(2,global.devicePixelRatio||1));
    renderer.setSize(container.clientWidth||720,container.clientHeight||720,false);
    renderer.outputColorSpace=THREE.SRGBColorSpace;
    renderer.toneMapping=THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure=1.34;
    renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
    renderer.domElement.style.width='100%';renderer.domElement.style.height='100%';renderer.domElement.style.display='block';
    renderer.domElement.style.cursor='grab';renderer.domElement.style.touchAction='none';container.appendChild(renderer.domElement);
    scene.add(new THREE.HemisphereLight(0xc8c7ff,0x171426,2.0));
    const light=(color,intensity,x,y,z)=>{const l=new THREE.DirectionalLight(color,intensity);l.position.set(x,y,z);scene.add(l);return l;};
    light(0xecdcff,3.5,2,6,-5);
    light(0x8b43ff,4.2,-3,4,2);
    light(0x35e7ff,1.6,3,2,2);
    const spot=new THREE.PointLight(0xa64eff,35,5);spot.position.set(-.5,3.3,-2);scene.add(spot);
    const a=create(THREE,scene,{scale:1,showHologram:true});
    let rotation=-.17,elevation=.02,zoom=8.5,dragging=false,lastX=0,lastY=0,disposed=false,frame=0;
    function resize(){const w=container.clientWidth||720,h=container.clientHeight||720;
      camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false);}
    resize();
    const observer=typeof ResizeObserver!=='undefined'?new ResizeObserver(resize):null;observer?.observe(container);
    const canvas=renderer.domElement;
    function down(e){dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(e.pointerId);canvas.style.cursor='grabbing';}
    function move(e){if(!dragging)return;rotation-=(e.clientX-lastX)*.009;elevation=clamp(elevation+(e.clientY-lastY)*.005,-.65,.65);lastX=e.clientX;lastY=e.clientY;}
    function up(){dragging=false;canvas.style.cursor='grab';}
    function wheel(e){e.preventDefault();zoom=clamp(zoom+e.deltaY*.008,4.8,12.5);}
    canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);
    canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up);canvas.addEventListener('wheel',wheel,{passive:false});
    function render(ms){if(disposed)return;const t=ms/1000;
      a.update(t);const target=new THREE.Vector3(0,2.47,0);
      camera.position.set(Math.sin(rotation)*zoom*Math.cos(elevation),2.47+Math.sin(elevation)*zoom,-Math.cos(rotation)*zoom*Math.cos(elevation));
      camera.lookAt(target);renderer.render(scene,camera);frame=global.requestAnimationFrame(render);
    }
    frame=global.requestAnimationFrame(render);
    return {avatar:a,scene,camera,renderer,resize,dispose(){
      disposed=true;global.cancelAnimationFrame(frame);observer?.disconnect();
      canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);
      canvas.removeEventListener('pointerup',up);canvas.removeEventListener('pointercancel',up);canvas.removeEventListener('wheel',wheel);
      a.dispose();renderer.dispose();canvas.remove();
    }};
  }

  global.NaveStarComms3D={version:VERSION,create,mount,index:CREW_INDEX};
})(typeof window!=='undefined'?window:globalThis);
